402: function dayKey(d = new Date()) {
403:   const y = d.getFullYear();
404:   const m = String(d.getMonth() + 1).padStart(2, '0');
405:   const day = String(d.getDate()).padStart(2, '0');
406:   return y + '-' + m + '-' + day;
407: }
408: function normDay(v) {
409:   if (typeof v !== 'string' || !v) return '';
410:   if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
411:   const t = Date.parse(v);
412:   return isFinite(t) ? dayKey(new Date(t)) : '';
413: }
414: function defaultState() {
415:   return {
416:     bal: 0, last: '', streak: 0, today: 0, todayDate: '',
417:     best: 0, gameToday: 0, gameDate: '', muted: false, plays: 0
418:   };
419: }
420: function loadState() {
421:   let s = defaultState();
422:   try {
423:     const raw = localStorage.getItem(STORE_KEY);
424:     if (raw) {
425:       const p = JSON.parse(raw);
426:       if (p && typeof p === 'object') s = Object.assign(s, p);
427:     }
428:   } catch (e) {}
429:   const tk = dayKey();
430:   s.bal = Math.max(0, Number(s.bal) || 0);
431:   s.streak = Math.max(0, Number(s.streak) || 0);
432:   s.best = Math.max(0, Number(s.best) || 0);
433:   s.today = Math.max(0, Number(s.today) || 0);
434:   s.gameToday = Math.max(0, Number(s.gameToday) || 0);
435:   s.last = normDay(s.last);
436:   s.todayDate = normDay(s.todayDate);
437:   s.gameDate = normDay(s.gameDate);
438:   if (s.todayDate !== tk) { s.todayDate = tk; s.today = 0; }
439:   if (s.gameDate !== tk) { s.gameDate = tk; s.gameToday = 0; }
440:   return s;
441: }
442: let S = loadState();
