449: /* ===== audio (WebAudio, no files) ===== */
450: let audioCtx = null;
451: function unlockAudio() {
452:   try {
453:     if (!audioCtx) {
454:       const AC = window.AudioContext || window.webkitAudioContext;
455:       if (AC) audioCtx = new AC();
456:     }
457:     if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
458:   } catch (e) { audioCtx = null; }
459:   return audioCtx;
460: }
461: function tone(freq, dur, type, vol, slideTo) {
462:   if (S.muted) return;
463:   const ac = unlockAudio();
464:   if (!ac) return;
465:   try {
466:     const o = ac.createOscillator();
467:     const g = ac.createGain();
468:     const t = ac.currentTime;
469:     o.type = type || 'sine';
470:     o.frequency.setValueAtTime(freq, t);
471:     if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(30, slideTo), t + dur);
472:     g.gain.setValueAtTime(0.0001, t);
473:     g.gain.exponentialRampToValueAtTime(vol || 0.035, t + 0.012);
474:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
475:     o.connect(g); g.connect(ac.destination);
476:     o.start(t); o.stop(t + dur + 0.02);
477:   } catch (e) {}
478: }
