482:   else if (kind === 'gem') { tone(660, .09, 'sine', .03, 990); tone(990, .16, 'triangle', .025, 1480); }
483:   else if (kind === 'jump') tone(280, .12, 'square', .02, 620);
484:   else if (kind === 'magnet') tone(180, .22, 'sawtooth', .022, 780);
485:   else if (kind === 'hit') { tone(180, .2, 'sawtooth', .035, 70); tone(90, .25, 'square', .025, 45); }
486:   else if (kind === 'start') { tone(523, .09, 'triangle', .025, 660); tone(784, .12, 'triangle', .022, 1046); }
487:   else if (kind === 'end') { tone(660, .12, 'triangle', .03, 440); tone(440, .22, 'sine', .025, 220); }
488:   else if (kind === 'claim') { tone(523, .09, 'triangle', .03, 660); tone(660, .09, 'triangle', .03, 784); tone(1046, .2, 'triangle', .028, 1318); }
489: }
