<script type="module">
import * as THREE from 'three';

/* =========================================================
   SOL RUSH 3D — complete daily game
   ========================================================= */
const $ = (id) => document.getElementById(id);
const gameDiv = $('game');
const canvasHost = gameDiv;
const DAY_MS = 86400000;
const START_TIME = 60;
const DAILY_CAP = 0.5;
const STORE_KEY = 'sol3d_v1';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;

function dayKey(d = new Date()) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}
function normDay(v) {
  if (typeof v !== 'string' || !v) return '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const t = Date.parse(v);
  return isFinite(t) ? dayKey(new Date(t)) : '';
}
function defaultState() {
  return {
    bal: 0, last: '', streak: 0, today: 0, todayDate: '',
    best: 0, gameToday: 0, gameDate: '', muted: false, plays: 0
  };
}
function loadState() {
  let s = defaultState();
  try {
    const raw = localStorage.getItem(STORE_KEY);
    if (raw) {
      const p = JSON.parse(raw);
      if (p && typeof p === 'object') s = Object.assign(s, p);
    }
  } catch (e) {}
  const tk = dayKey();
  s.bal = Math.max(0, Number(s.bal) || 0);
  s.streak = Math.max(0, Number(s.streak) || 0);
  s.best = Math.max(0, Number(s.best) || 0);
  s.today = Math.max(0, Number(s.today) || 0);
  s.gameToday = Math.max(0, Number(s.gameToday) || 0);
  s.last = normDay(s.last);
  s.todayDate = normDay(s.todayDate);
  s.gameDate = normDay(s.gameDate);
  if (s.todayDate !== tk) { s.todayDate = tk; s.today = 0; }
  if (s.gameDate !== tk) { s.gameDate = tk; s.gameToday = 0; }
  return s;
}
let S = loadState();

function save() {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(S)); } catch (e) {}
}
function vibrate(ms) { try { navigator.vibrate && navigator.vibrate(ms); } catch (e) {} }

/* ===== audio (WebAudio, no files) ===== */
let audioCtx = null;
function unlockAudio() {
  try {
    if (!audioCtx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (AC) audioCtx = new AC();
    }
    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
  } catch (e) { audioCtx = null; }
  return audioCtx;
}
function tone(freq, dur, type, vol, slideTo) {
  if (S.muted) return;
  const ac = unlockAudio();
  if (!ac) return;
  try {
    const o = ac.createOscillator();
    const g = ac.createGain();
    const t = ac.currentTime;
    o.type = type || 'sine';
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(30, slideTo), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol || 0.035, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(ac.destination);
    o.start(t); o.stop(t + dur + 0.02);
  } catch (e) {}
}
