  else if (kind === 'jump') tone(280, .12, 'square', .02, 620);
  else if (kind === 'magnet') tone(180, .22, 'sawtooth', .022, 780);
  else if (kind === 'hit') { tone(180, .2, 'sawtooth', .035, 70); tone(90, .25, 'square', .025, 45); }
  else if (kind === 'start') { tone(523, .09, 'triangle', .025, 660); tone(784, .12, 'triangle', .022, 1046); }
  else if (kind === 'end') { tone(660, .12, 'triangle', .03, 440); tone(440, .22, 'sine', .025, 220); }
  else if (kind === 'claim') { tone(523, .09, 'triangle', .03, 660); tone(660, .09, 'triangle', .03, 784); tone(1046, .2, 'triangle', .028, 1318); }
}

