function makeCoin(kind) {
  const g = new THREE.Group();
  if (kind === 'gem') {
    const gem = new THREE.Mesh(gemGeo, gemMat);
    g.add(gem);
    const halo = new THREE.Sprite(gemGlowMat);
    halo.scale.set(1.7, 1.7, 1);
    g.add(halo);
    g.userData = { kind: 'gem', spin: 1.8, phase: Math.random() * 6.28, baseY: 1.2, value: 1 };
  } else {
    const disc = new THREE.Mesh(coinDiscGeo, coinDiscMat);
    disc.rotation.x = Math.PI / 2;
    g.add(disc);
    const rim = new THREE.Mesh(coinRimGeo, coinRimMat);
    g.add(rim);
    const inner = new THREE.Mesh(coinInnerGeo, coinInnerMat);
    inner.rotation.x = Math.PI / 2;
    g.add(inner);
    const halo = new THREE.Sprite(coinGlowMat);
    halo.scale.set(1.55, 1.55, 1);
    g.add(halo);
    g.userData = { kind: 'coin', spin: 1.2 + Math.random() * 1.3, phase: Math.random() * 6.28, baseY: 0.95, value: 1 };
  }
  return g;
}
const coins = [];
let gemRespawnAt = 0;

function randomArenaPos(minR, maxR) {
  const a = Math.random() * Math.PI * 2;
  const r = minR + Math.random() * (maxR - minR);
  return [Math.cos(a) * r, Math.sin(a) * r];
}
function spawnCoin(kind) {
  kind = kind || 'coin';
  const c = makeCoin(kind);
  let x = 0, z = 0;
  for (let tries = 0; tries < 12; tries++) {
    const p = randomArenaPos(2.2, ARENA - 1.4);
    x = p[0]; z = p[1];
    let ok = true;
    for (const o of coins) {
      if ((o.position.x - x) * (o.position.x - x) + (o.position.z - z) * (o.position.z - z) < 2.2) { ok = false; break; }
    }
    if (ok) break;
  }
  const high = Math.random() < 0.28;
  const y = kind === 'gem' ? (Math.random() < 0.5 ? 1.15 : 2.35) : (high ? 2.15 : 0.95);
  c.position.set(x, y, z);
  c.userData.baseY = y;
  scene.add(c);
  coins.push(c);
  return c;
}

