/* ===== daily reward ===== */
function claimDaily(silent) {
  const tk = dayKey();
  if (S.last === tk) {
    if (!silent) toast('استلمت مكافأة اليوم بالفعل — عد غداً');
    return false;
  }
  const yk = dayKey(new Date(Date.now() - DAY_MS));
  S.streak = S.last === yk ? S.streak + 1 : 1;
  const reward = S.streak >= 3 ? 1 : 0.5;
  S.bal += reward;
  S.today += reward;
  S.last = tk;
  save();
  sfx('claim');
  vibrate(40);
  toast('🎉 مكافأة يوم ' + S.streak + ': +' + reward.toFixed(2) + ' SOL تجريبي');
  floatText('+' + reward.toFixed(2) + ' SOL', new THREE.Vector3(player.position.x, 1.6, player.position.z), 'good');
  burst(new THREE.Vector3(player.position.x, 1.2, player.position.z), 0xf6e27a, 18);
  render();
  return true;
}

/* ===== round lifecycle ===== */
function clearDynamic() {
  while (coins.length) {
    const c = coins.pop();
    scene.remove(c);
  }
  while (hazards.length) {
    const h = hazards.pop();
    scene.remove(h);
  }
  while (particles.length) {
    const p = particles.pop();
    scene.remove(p);
    if (p.material) p.material.dispose();
  }
}
function resetRound() {
  round.active = true;
  round.timeLeft = START_TIME;
  round.endsAt = performance.now() + START_TIME * 1000;
  round.pausedAt = 0;
  round.score = 0;
  round.coins = 0;
  round.earned = 0;
  round.combo = 1;
  round.comboTimer = 0;
  round.comboCount = 0;
  round.jumpY = 0;
  round.vy = 0;
  round.hitUntil = 0;
  round.magnetUntil = 0;
  round.magnetReadyAt = 0;
  round.shake = 0;
  gemRespawnAt = 0;
  vel.set(0, 0, 0);
  player.position.set(0, 0, 0);
  player.rotation.y = Math.PI;
  targetFacing = Math.PI;
  ang = 0;
  for (const k in keys) keys[k] = false;
  joy.x = 0; joy.y = 0; joy.active = false; joy.id = null;
  joyKnob.style.transform = 'translate(0,0)';
  lookTarget.set(0, 1.05, 0);
  camera.position.set(0, camHeight, camDist);
  clearDynamic();
  for (let i = 0; i < 17; i++) spawnCoin('coin');
  spawnCoin('gem');
  for (let i = 0; i < 5; i++) spawnHazard();
  $('roundHud').hidden = false;
  $('controls').hidden = false;
  updateHud();
}
function startRound() {
  unlockAudio();
  document.getElementById('overlay').classList.remove('show');
  document.body.classList.add('playing');
  resetRound();
  sfx('start');
  toast('انطلق! اجمع العملات وتجنب الشموع الحمراء', 2400);
}
function endRound() {
  if (!round.active) return;
  round.active = false;
  $('controls').hidden = true;
  $('roundHud').hidden = true;
  magnetRing.visible = false;
  magnetLight.intensity = 0;
  document.body.classList.remove('playing');
  S.best = Math.max(S.best, round.score);
  S.plays = (S.plays || 0) + 1;
  save();
  sfx('end');
  vibrate([30, 50, 30]);
  const stars = round.coins >= 42 ? 3 : round.coins >= 24 ? 2 : round.coins >= 10 ? 1 : 0;
  $('stars').textContent = '★'.repeat(stars) + '☆'.repeat(3 - stars);
  $('resCoins').textContent = round.coins;
  $('resScore').textContent = round.score;
  $('resEarn').textContent = round.earned.toFixed(2);
  $('resBest').textContent = S.best;
  let title = 'انتهى التحدي!';
  if (stars === 3) title = '🏆 أسطورة SOL!';
  else if (stars === 2) title = '⚡ أداء ممتاز!';
  else if (stars === 1) title = '👍 بداية جيدة';
  $('resultTitle').textContent = title;
  let msg = '';
  if (stars === 3) msg = 'جمعت ' + round.coins + ' عملة — نتيجة تليق بالبطل.';
  else if (stars === 2) msg = 'اقتربت من الثلاث نجوم — جرّب الكومبو والمغناطيس أكثر.';
  else if (stars === 1) msg = 'استخدم المغناطيس عند ازدحام العملات، واقفز فوق الشموع الحمراء.';
  else msg = 'لا بأس — راقب الشموع الحمراء واجمع العملات القريبة أولاً.';
  if (S.gameToday >= DAILY_CAP - 0.0001) msg += ' وصلت حد أرباح اللعب اليومي 0.50 SOL — عد غداً.';
  $('resultMsg').textContent = msg;
  render();
  showResult();
}
function showResult() {
  $('startSheet').hidden = true;
